#!/usr/bin/env node
/**
 * Starts the Next.js dev server on port 3002.
 *
 * `next dev` cannot reuse a `.next` directory generated by `next build`, and
 * deleting that directory while another dev server is running leaves the live
 * process without its manifests (it then crashes on the next request).
 *
 * This launcher only clears `.next` when the port is free, and refuses to start
 * a second instance instead of breaking the one that is already running.
 */
import { spawn } from 'node:child_process';
import fs from 'node:fs';
import net from 'node:net';
import path from 'node:path';
import process from 'node:process';

const PORT = Number(process.env.PORT || 3002);

function isPortFree(port) {
  return new Promise((resolve) => {
    const server = net.createServer();
    server.unref();
    server.once('error', () => resolve(false));
    server.once('listening', () => server.close(() => resolve(true)));
    server.listen(port, '127.0.0.1');
  });
}

const free = await isPortFree(PORT);

if (!free) {
  console.error(
    `\nPort ${PORT} is already in use. The existing server was left untouched.\n` +
      `Open http://localhost:${PORT} or stop that process before starting another one.\n`
  );
  process.exit(0);
}

const nextDir = path.join(process.cwd(), '.next');
if (fs.existsSync(nextDir)) {
  fs.rmSync(nextDir, { recursive: true, force: true });
}

const nextBin = path.join(process.cwd(), 'node_modules', 'next', 'dist', 'bin', 'next');
const child = spawn(process.execPath, [nextBin, 'dev', '-p', String(PORT)], {
  stdio: 'inherit',
  env: process.env,
});

child.on('exit', (code, signal) => {
  if (signal) process.kill(process.pid, signal);
  else process.exit(code ?? 0);
});

for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => {
    if (!child.killed) child.kill(signal);
  });
}
